using System.IO;
namespace DesktopBox;
internal static class SelfTest {
 internal static int Run(){var root=Path.Combine(Path.GetTempPath(),"DesktopBox-test-"+Guid.NewGuid());Directory.CreateDirectory(root);int checks=0;try{var source=Path.Combine(root,"source");var dest=Path.Combine(root,"dest");Directory.CreateDirectory(source);Directory.CreateDirectory(dest);var file=Path.Combine(source,"hello.txt");File.WriteAllText(file,"original");var target=FileActions.MoveInto(file,dest);Assert(!File.Exists(file)&&File.ReadAllText(target)=="original");File.WriteAllText(file,"second");try{FileActions.MoveInto(file,dest);throw new Exception("冲突未拒绝");}catch(IOException){}Assert(File.ReadAllText(file)=="second"&&File.ReadAllText(target)=="original");var folder=Path.Combine(source,"sub");Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,"child"),"nested");FileActions.MoveInto(folder,dest);Assert(!Directory.Exists(folder)&&File.Exists(Path.Combine(dest,"sub","child")));var config=new BoxConfig();config.Entries.Add(file);config.Entries.Remove(file);Assert(File.Exists(file));try{FileActions.MoveInto(file,Path.Combine(root,"missing"));throw new Exception("失效路径未拒绝");}catch(DirectoryNotFoundException){}Assert(File.Exists(file));var old=Store.PathName;try{Store.PathName=Path.Combine(root,"state","test.json");var settings=new Settings();settings.Boxes.Add(new BoxConfig{Folder=dest,Name="映射",Locked=true,View="详细信息"});Store.Save(settings);var loaded=Store.Load();Assert(loaded.Boxes.Single().Folder==dest&&loaded.Boxes.Single().Locked);loaded.Boxes.Clear();Store.Save(loaded);Assert(File.Exists(target)&&Directory.Exists(dest));}finally{Store.PathName=old;}File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"self-test.txt"),$"PASS: {checks} checks\n");return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"self-test.txt"),ex.ToString());return 1;}finally{Directory.Delete(root,true);}void Assert(bool value){if(!value)throw new Exception("验证失败");checks++;}}
}
